auto func (auto value){  
    std::unordered_set<decltype(value)> unique_elements{std::begin(value), std::end(value)};
    return unique_elements.size() == std::size(value);
}

auto func (auto value){ 
    return std::all_of(value.begin(), value.end(), [&](const auto& elem) { 
        return std::set(value.begin(), value.end()).size() == value.size(); 
    });
}

auto func (auto value){ 
    std::unordered_set<decltype(value)> s;
    for(auto&& e : value) s.insert(e);
    return s.size() == value.size();
}
